const cards = $input.first().json.cards || [];
const results = [];

for (const cardHtml of cards) {
  // Пропускаем карточку, если это "Сорт недели"
  if (/сорт недели/i.test(cardHtml)) {
    continue;
  }

  // Извлекаем ссылку и название из .tc-tile__title a
  const titleMatch = cardHtml.match(/class="[^"]*tc-tile__title[^"]*"[\s\S]*?<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/i);
  // Извлекаем картинку из .tc-tile__picture img
  const imgMatch = cardHtml.match(/class="[^"]*tc-tile__picture[^"]*"[\s\S]*?<img[^>]*src="([^"]+)"/i);

  if (titleMatch) {
    const link = titleMatch[1].trim();
    const title = titleMatch[2].replace(/<[^>]+>/g, '').trim();
    const img = imgMatch ? imgMatch[1].trim() : '';

    // Дополнительная проверка по названию
    if (title && !/сорт недели/i.test(title)) {
      results.push({
        json: {
          title,
          link,
          img
        }
      });
    }
  }
}

return results;

