const splitItems = $('Карточки товаров').all();
const processedItems = $('Проверка нахождения ключевых слов').all();
const notionFlavors = $('Get many database pages (вкусы)').all();
const notionCountries = $('Get many database pages (страны)').all();
const notionRegions = $('Get many database pages (регионы)').all();

// === НОВОЕ: существующие страницы (лоты) для проверки дублей ===
const existingLots = $('Get many database pages(зёрна)').all();

// МАКСИМАЛЬНО ЖЕСТКАЯ ОЧИСТКА (как было)
function cleanStr(str) {
  if (!str) return '';
  return str
    .replace(/\(.*/g, '')
    .replace(/[^\wа-яё\s-]/gi, '')
    .replace(/[\u00A0\s]+/g, ' ')
    .trim()
    .toLowerCase();
}

// Нормализация названия лота для сравнения
function normalizeTitle(str) {
  if (!str) return '';
  return String(str)
    .toLowerCase()
    .replace(/\(.*?\)/g, ' ')
    .replace(/[^\wа-яё\s-]/gi, ' ')
    .replace(/\b\d+\s*(г|гр|kg|кг|мл)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function firstWords(str, n) {
  return str.split(' ').slice(0, n).join(' ');
}

// === Карта существующих лотов: нормализованное имя -> id ===
const existingMap = new Map();
for (const page of existingLots) {
  const props = page.json.properties || {};
  let title = '';

  for (const prop of Object.values(props)) {
    if (prop?.type === 'title' && Array.isArray(prop.title)) {
      title = prop.title.map(t => t.plain_text).join('');
      break;
    }
  }
  if (!title) title = page.json.name || page.json.title || '';

  const key = normalizeTitle(title);
  if (key && page.json.id) {
    existingMap.set(key, page.json.id);
  }
}

function findExistingId(title) {
  const key = normalizeTitle(title);
  if (!key) return null;

  // 1) точное совпадение после нормализации
  if (existingMap.has(key)) return existingMap.get(key);

  // 2) нечёткое: вхождение / совпадение первых слов
  for (const [existingKey, id] of existingMap.entries()) {
    if (
      existingKey.includes(key) ||
      key.includes(existingKey) ||
      firstWords(existingKey, 3) === firstWords(key, 3)
    ) {
      return id;
    }
  }
  return null;
}

// === Существующие хелперы (как было) ===
function buildLookupMap(pages) {
  const map = {};
  for (const page of pages) {
    let rawTitle = page.json.name || '';

    if (!rawTitle && page.json.properties) {
      for (const prop of Object.values(page.json.properties)) {
        if (prop?.type === 'title' && Array.isArray(prop.title)) {
          rawTitle = prop.title.map(t => t.plain_text).join('');
          break;
        }
      }
    }

    const cleanTitle = cleanStr(rawTitle);

    if (cleanTitle && page.json.id) {
      map[cleanTitle] = page.json.id;
    }
  }
  return map;
}

const flavorMap = buildLookupMap(notionFlavors);
const countryMap = buildLookupMap(notionCountries);
const regionMap = buildLookupMap(notionRegions);

function mapNamesToIds(namesArray, lookupMap) {
  if (!Array.isArray(namesArray)) return [];
  return namesArray.map(name => {
    const cleanName = cleanStr(name);
    return lookupMap[cleanName];
  }).filter(Boolean);
}

// === Собираем результат + проверка дублей ===
return processedItems.map((item, index) => {
  const baseInfo = splitItems[index]?.json || {};
  const data = item.json;
  const title = baseInfo.title;

  const existingPageId = findExistingId(title);

  return {
    json: {
      ...data,
      title,
      link: baseInfo.link,
      img: baseInfo.img,
      flavorIds: mapNamesToIds(data.descriptors, flavorMap),
      countryIds: mapNamesToIds(data.countries, countryMap),
      regionIds: mapNamesToIds(data.regions, regionMap),
      existingPageId: existingPageId || null,
      isDuplicate: Boolean(existingPageId)
    }
  };
});

