return $input.all().map(item => {
  const rawDesc = item.json.desc || [];
  const cleanSpecs = {};

  rawDesc.forEach(text => {
    // 1. Полностью вырезаем любые теги <svg>...</svg> вместе с содержимым
    let cleanText = text.replace(/<svg[\s\S]*?<\/svg>/g, '');

    // 2. Убираем слово info, квадратные скобки и лишний мусор
    cleanText = cleanText
      .replace(/info/gi, '')
      .replace(/\[data:image[^\]]*\]/g, '')
      .trim();

    // 3. Разделяем по переносам строк
    const parts = cleanText.split(/\n+/).map(p => p.trim()).filter(p => p.length > 0);

    if (parts.length >= 2) {
      const key = parts[0];
      // Соединяем всё, что идет после ключа, в единое чистое значение
      const value = parts.slice(1).join(', ').replace(/^[,,\s]+/, '').trim();
      cleanSpecs[key] = value;
    }
  });

  return {
    json: {
      descriptors: item.json.descriptors || [],
      specs: cleanSpecs
    }
  };
});

