// Функция нормализации одного дескриптора
function normalizeDescriptor(raw) {
  const lower = raw.trim().toLowerCase();
  for (const entry of descriptorsDict) {
    if (entry.stems.some(stem => lower.includes(stem))) {
      return entry.norm;
    }
  }
  // Если слова нет в словаре — возвращаем как есть, но с заглавной буквы
  return lower.charAt(0).toUpperCase() + lower.slice(1);
}

