  const foundCountries = knownCountries.filter(country => locationText.includes(country)).map(c => c.charAt(0).toUpperCase() + c.slice(1));
  const foundRegions = knownRegions.filter(region => locationText.includes(region)).map(r => r.charAt(0).toUpperCase() + r.slice(1));

  // 3. Обработка
  const rawProcessing = (specs['Обработка'] || specs['Способ обработки'] || Object.values(specs).join(' ')).toLowerCase();
