  for (const proc of processingConfig) {
    if (proc.keywords.some(kw => new RegExp(`(^|[^а-яёa-z])${kw}`, 'i').test(rawProcessing))) {
      processing.push(proc.name);
    }
  }

  results.push({
    json: {
      ...itemData,
      countries: foundCountries,
      regions: foundRegions,
      processing: processing,
      descriptors: topDescriptors
    }
  });
}
return results;
